package com.auth.oauth

import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable
import java.net.{URI, URLDecoder, URLEncoder}
import java.nio.charset.StandardCharsets
import java.time.Instant

object AuditLog {
  private val entries = mutable.ArrayBuffer.empty[String]

  def log(event: String, details: Map[String, String]): Unit = {
    val timestamp = Instant.now().toString
    val sanitized = details.map { case (k, v) =>
      s"$k=${v.replaceAll("[\\r\\n]", "")}"
    }.mkString(", ")
    entries.synchronized {
      entries += s"[$timestamp] $event: $sanitized"
    }
  }

  def getEntries: Seq[String] = entries.synchronized { entries.toSeq }
}

class HmacVerifier(secret: Array[Byte]) {
  private val algorithm = "HmacSHA256"

  def sign(data: String): Array[Byte] = {
    val mac = Mac.getInstance(algorithm)
    mac.init(new SecretKeySpec(secret, algorithm))
    mac.doFinal(data.getBytes(StandardCharsets.UTF_8))
  }

  def verify(data: String, signature: Array[Byte]): Boolean = {
    val expected = sign(data)
    MessageDigest.isEqual(expected, signature)
  }
}

class RedirectUriValidator(allowedDomains: Set[String]) {

  private def normalizeUri(uri: String): String = {
    val decoded = URLDecoder.decode(uri, StandardCharsets.UTF_8.name())
    decoded.toLowerCase.trim
  }

  private def extractHost(uri: String): Option[String] = {
    try {
      val parsed = new URI(uri)
      Option(parsed.getHost)
    } catch {
      case _: Exception => None
    }
  }

  def isAllowed(redirectUri: String): Boolean = {
    val normalized = normalizeUri(redirectUri)
    extractHost(normalized) match {
      case Some(host) =>
        allowedDomains.exists(domain => host == domain || host.endsWith("." + domain))
      case None => false
    }
  }
}

class OAuthStateManager(hmacVerifier: HmacVerifier) {

  def generateState(clientId: String, redirectUri: String): String = {
    val timestamp = Instant.now().getEpochSecond.toString
    val payload = s"$clientId|$redirectUri|$timestamp"
    val signature = hmacVerifier.sign(payload)
    val encodedSig = Base64.getUrlEncoder.withoutPadding().encodeToString(signature)
    val encodedPayload = Base64.getUrlEncoder.withoutPadding().encodeToString(
      payload.getBytes(StandardCharsets.UTF_8)
    )
    s"$encodedPayload.$encodedSig"
  }

  def validateState(state: String, expectedClientId: String, expectedRedirectUri: String): Option[String] = {
    try {
      val parts = state.split("\\.", 2)
      if (parts.length != 2) return None

      val payload = new String(
        Base64.getUrlDecoder.decode(parts(0)), StandardCharsets.UTF_8
      )
      val signature = Base64.getUrlDecoder.decode(parts(1))

      if (!hmacVerifier.verify(payload, signature)) return None

      val fields = payload.split("\\|", 3)
      if (fields.length != 3) return None
      if (fields(0) != expectedClientId) return None
      if (fields(1) != expectedRedirectUri) return None

      val timestamp = fields(2).toLong
      val now = Instant.now().getEpochSecond
      if (now - timestamp > 600) return None

      Some(fields(1))
    } catch {
      case _: Exception => None
    }
  }
}

class OAuthServer(
  secret: Array[Byte],
  allowedDomains: Set[String]
) {
  private val hmacVerifier = new HmacVerifier(secret)
  private val uriValidator = new RedirectUriValidator(allowedDomains)
  private val stateManager = new OAuthStateManager(hmacVerifier)

  def authorize(clientId: String, redirectUri: String): Either[String, String] = {
    AuditLog.log("authorize_request", Map(
      "client_id" -> clientId,
      "redirect_uri" -> redirectUri
    ))

    if (!uriValidator.isAllowed(redirectUri)) {
      AuditLog.log("authorize_rejected", Map(
        "client_id" -> clientId,
        "redirect_uri" -> redirectUri,
        "reason" -> "invalid_redirect_uri"
      ))
      return Left("Invalid redirect URI")
    }

    val state = stateManager.generateState(clientId, redirectUri)
    AuditLog.log("authorize_approved", Map(
      "client_id" -> clientId,
      "redirect_uri" -> redirectUri
    ))
    Right(state)
  }

  def callback(state: String, clientId: String, redirectUri: String, code: String): Either[String, String] = {
    stateManager.validateState(state, clientId, redirectUri) match {
      case Some(validatedUri) =>
        AuditLog.log("callback_success", Map(
          "client_id" -> clientId,
          "redirect_uri" -> validatedUri
        ))
        Right(s"$validatedUri?code=${URLEncoder.encode(code, StandardCharsets.UTF_8.name())}")
      case None =>
        AuditLog.log("callback_failed", Map(
          "client_id" -> clientId,
          "reason" -> "invalid_state"
        ))
        Left("Invalid state parameter")
    }
  }
}
